import datetime

import factpin

EXPECTED = """\
% ---- Generated by factpin 0.2.0 ----
% ---- Output date: 2026-08-11 ----

\\declconstgroup{auroc}{round-mode=places,round-precision=3}{}{ci}
\\declconstgroup{latency}{round-mode=places,round-precision=1}{\\milli\\second}{plain}

\\declconst{auroc_a_mean}{0.5}{auroc}
\\declconst{auroc_a_ci}{0.5,0.45,0.55}{auroc}
\\declconst{train_time}{12.34}{latency}
\\declconst{n_patients}{1234}{}
\\declconsttext{best_model}{Logistic regression}
"""


def build(tmp_path=None):
    ctx = factpin.Context(
        "results", path=tmp_path or ".", date=datetime.date(2026, 8, 11)
    )
    ctx.add_group("auroc", places=3, format="ci")
    ctx.add_group("latency", unit=r"\milli\second", places=1)
    ctx.add("auroc_a_mean", value=0.5, group="auroc")
    ctx.add("auroc_a_ci", values=[0.5, 0.45, 0.55], group="auroc")
    ctx.add("train_time", value=12.34, group="latency")
    ctx.add("n_patients", value=1234)
    ctx.add_text("best_model", "Logistic regression")
    return ctx


def test_render_matches_golden():
    assert build().render() == EXPECTED


def test_write_lands_at_output_path(tmp_path):
    ctx = build(tmp_path)
    written = ctx.write()
    assert written == tmp_path / "results.tex"
    assert written.read_text(encoding="utf-8") == EXPECTED


def test_write_creates_missing_directories(tmp_path):
    ctx = build(tmp_path / "out" / "nested")
    written = ctx.write()
    assert written.exists()


def test_write_accepts_explicit_path(tmp_path):
    ctx = build(tmp_path)
    written = ctx.write(tmp_path / "elsewhere.tex")
    assert written.name == "elsewhere.tex"


def test_declaration_order_is_preserved():
    # The generated file should read like the analysis that produced it.
    ctx = factpin.Context("results")
    for name in ["zeta", "alpha", "mu"]:
        ctx.add(name, value=1)
    assert [c.name for c in ctx.constants] == ["zeta", "alpha", "mu"]


def test_sty_is_shipped_and_installable(tmp_path):
    assert factpin.sty_path().is_file()
    installed = factpin.install_sty(tmp_path)
    assert installed == tmp_path / "factpin.sty"
    assert installed.read_text(encoding="utf-8") == factpin.sty_path().read_text(
        encoding="utf-8"
    )


def test_cli_install_sty_without_destination_prints_the_file(capsys, tmp_path, monkeypatch):
    from factpin.__main__ import main

    monkeypatch.chdir(tmp_path)
    assert main(["install-sty"]) == 0
    assert capsys.readouterr().out == factpin.sty_path().read_text(encoding="utf-8")
    # Printing must not also drop a copy into the working directory.
    assert not (tmp_path / "factpin.sty").exists()


def test_cli_install_sty_with_destination_copies(capsys, tmp_path):
    from factpin.__main__ import main

    assert main(["install-sty", str(tmp_path)]) == 0
    assert capsys.readouterr().out.strip() == str(tmp_path / "factpin.sty")
    assert (tmp_path / "factpin.sty").is_file()
